function r(e){if(!e)return"Erro ao processar pagamento. Verifique os dados e tente novamente.";const o=e.toLowerCase();return o.includes("card verification failed")||o.includes("could not create credit card")||o.includes("não foi possível criar o cartão de crédito")||o.includes("a verificação do cartão falhou")?"Cartão recusado pelo banco. Verifique no app se compras online estão liberadas ou tente outro cartão.":o.includes("card declined")||o.includes("cartão recusado")?"Cartão recusado. Verifique os dados ou use outro cartão.":o.includes("invalid card number")||o.includes("número do cartão inválido")?"Número do cartão inválido. Verifique os dados digitados.":e}export{r as n};
